function backoff_delay(int $attempt): int
{
    // $attempt is 1-based: 1 = the first retry.
    return min(2 ** $attempt, 3600);
}

backoff_delay(1);   // 2
backoff_delay(5);   // 32
backoff_delay(10);  // 1024
backoff_delay(12);  // 3600  (2 ** 12 = 4096, capped)
backoff_delay(100); // 3600  (the cap holds forever)

function should_retry(int $attempt, int $maxAttempts): bool
{
    // $attempt has already run (1-based); retry only while budget remains.
    return $attempt < $maxAttempts;
}

function backoff_plan(int $maxAttempts, int $baseSeconds = 5, int $capSeconds = 3600): array
{
    $plan = [];
    $retries = $maxAttempts - 1; // one wait before each retry, none after the last

    for ($i = 0; $i < $retries; $i++) {
        $plan[] = min($baseSeconds * (2 ** $i), $capSeconds);
    }

    return $plan;
}

backoff_plan(4, 5);     // [5, 10, 20]
backoff_plan(1, 5);     // [] - a single attempt never retries
backoff_plan(5, 5, 15); // [5, 10, 15, 15]
backoff_plan(3, 2);     // [2, 4]

